/**
 * Auto-generate Figma Code Connect mapping files from the component registry.
 *
 * Each generated file maps a Figma component to its Adhar UI code equivalent,
 * including variant property mappings for React, Vue, Solid, Svelte, and Angular.
 *
 * @module
 */

/** A generated Code Connect file. */
export interface CodeConnectFile {
  /** File path (e.g., "components/button.figma.ts"). */
  path: string;
  /** File content. */
  content: string;
  /** Component name. */
  componentName: string;
}

/** Minimal component entry from the registry. */
interface ComponentEntry {
  name: string;
  title: string;
}

/** CVA-like variant config. */
interface VariantConfig {
  variants?: Record<string, Record<string, string>>;
  defaultVariants?: Record<string, string>;
}

/**
 * Generate Code Connect files for all components.
 *
 * @param components - Component entries from the registry
 * @param framework - Target framework for code examples
 * @param figmaFileKey - Figma file key for component URLs
 * @returns Array of generated files
 */
export function generateCodeConnect(
  components: ComponentEntry[],
  framework: 'react' | 'vue' | 'solid' | 'svelte' | 'angular' = 'react',
  figmaFileKey = 'YOUR_FILE_KEY',
): CodeConnectFile[] {
  return components.map((comp) => generateComponentConnect(comp, framework, figmaFileKey));
}

/**
 * Generate a Code Connect file for a single component.
 *
 * @param component - Component metadata
 * @param framework - Target framework
 * @param figmaFileKey - Figma file key
 * @param variantConfig - Optional CVA variant config for prop mapping
 * @returns Generated file
 */
export function generateComponentConnect(
  component: ComponentEntry,
  framework: 'react' | 'vue' | 'solid' | 'svelte' | 'angular' = 'react',
  figmaFileKey = 'YOUR_FILE_KEY',
  variantConfig?: VariantConfig,
): CodeConnectFile {
  const name = component.name;
  const pascal = name.split('-').map((s) => s.charAt(0).toUpperCase() + s.slice(1)).join('');
  const slug = name;

  // Generate variant prop mappings
  const propMappings: string[] = [];
  const exampleProps: string[] = [];

  if (variantConfig?.variants) {
    for (const [axisName, values] of Object.entries(variantConfig.variants)) {
      const figmaPropName = axisName.charAt(0).toUpperCase() + axisName.slice(1);
      const valueEntries = Object.keys(values)
        .map((v) => `      ${v.charAt(0).toUpperCase() + v.slice(1)}: "${v}"`)
        .join(',\n');

      propMappings.push(
        `    ${axisName}: figma.enum("${figmaPropName}", {\n${valueEntries}\n    })`,
      );
      exampleProps.push(`\${${axisName}}`);
    }
  }

  // Add children prop for components that accept content
  propMappings.push('    children: figma.children("Content")');

  const propsBlock = propMappings.join(',\n');

  // Generate framework-specific example
  let exampleCode: string;
  const variantAttrs = exampleProps.length > 0
    ? ' ' + Object.keys(variantConfig?.variants ?? {}).map((k) => `${k}="\${${k}}"`).join(' ')
    : '';

  switch (framework) {
    case 'vue':
      exampleCode = `<${pascal}${variantAttrs}>\${children}</${pascal}>`;
      break;
    case 'svelte':
      exampleCode = `<${pascal}${variantAttrs}>\${children}</${pascal}>`;
      break;
    case 'angular':
      exampleCode = `<${slug}${variantAttrs}>\${children}</${slug}>`;
      break;
    default: // react, solid
      exampleCode = `<${pascal}${variantAttrs}>\${children}</${pascal}>`;
  }

  const content = `/**
 * Figma Code Connect mapping for ${pascal} component.
 * Auto-generated by @adhar-ui/code-connect
 *
 * Links the Figma "${pascal}" component to Adhar UI code,
 * enabling code snippets in Figma Dev Mode.
 */
import figma from "@figma/code-connect"

figma.connect(
  "https://figma.com/file/${figmaFileKey}?node-id=${slug.toUpperCase()}_NODE_ID",
  {
    props: {
${propsBlock}
    },
    example: ({ ${[...Object.keys(variantConfig?.variants ?? {}), 'children'].join(', ')} }) =>
      \`${exampleCode}\`,
  }
)
`;

  return {
    path: `components/${slug}.figma.ts`,
    content,
    componentName: name,
  };
}
